{"command":"node -e "
const base='http://127.0.0.1:8787';
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{
  await fetch(base+'/api/control',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reset:true})});
  const plan=await(await fetch(base+'/api/agent/plan')).json();
  console.log('PLAN:',plan.plan.map(s=>s.step+'.'+s.name).join(' '));
  const s0=await(await fetch(base+'/api/agent/state')).json();
  console.log('T0 step',s0.currentStep,s0.decision.name,'blocked=',s0.decision.blocked||false);

  // 执行完整决策链：循环 decide 直到完成（期间仿真自然推进）
  for(let i=0;i<60;i++){
    const d=await(await fetch(base+'/api/agent/decide',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'})).json();
    const step=d.decision.step;
    if(i%5===0||d.decision.act||d.decision.blocked) console.log('T'+i,'step',step,d.decision.name, d.executed?('exec:'+d.executed.tool):'observe/judge');
    if(d.state.phase==='completed'){console.log('COMPLETED at T'+i);break;}
    await sleep(1000);
  }
  const sf=await(await fetch(base+'/api/agent/state')).json();
  console.log('FINAL phase:',sf.phase,'success:',sf.decisionEvents.filter(e=>e.type==='decision').length,'decision events');
  const st=await(await fetch(base+'/api/state')).json();
  console.log('metrics:',JSON.stringify(st.state.metrics));
  console.log('route:',JSON.stringify(st.state.route));
  console.log('vms:',st.state.vms.message,'light:',st.state.light.on,st.state.light.brightness);
})();
"","timeoutMs":80000}

{"command":"node -e "
const base='http://127.0.0.1:8787';
(async()=>{
  await fetch(base+'/api/control',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reset:true})});
  let i=0;
  while(true){
    i++;
    const r=await fetch(base+'/api/agent/decide',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});
    const j=await r.json();
    console.log('call',i,'status',r.status, j.decision? ('step '+j.decision.step+' '+j.decision.name+' act='+j.decision.act+' blocked='+!!j.decision.blocked) : ('NO decision: '+JSON.stringify(j).slice(0,120)));
    if(r.status!==200){console.log('RAW:',JSON.stringify(j).slice(0,300));break;}
    if(j.state.phase==='completed'){console.log('COMPLETED');break;}
    if(i>=40)break;
    await new Promise(res=>setTimeout(res,1000));
  }
})();
"","timeoutMs":60000}

