    }
  }
  assert(allHaveFields, '所有日志均含 observation/decision/tool/result/next 字段');

  // 2) observation 格式
  const obsOk = logs.every((l) => /^visibility=\d+m, wind=/.test(l.observation));
  assert(obsOk, 'observation 均形如 "visibility=XXm, wind=YYm/s"');

  // 3) result 取值集合
